   106  template <typename ARG, typename SUBRS>
   107  struct CSInterpEnv : InterpEnv<ARG>
   108  {
   109    inline void init (const ByteStr &str, const SUBRS &globalSubrs_, const SUBRS &localSubrs_)
   110    {
   111      InterpEnv<ARG>::init (str);
   112
   113      context.init (str, CSType_CharString);
   114      seen_moveto = true;
   115      seen_hintmask = false;
   116      hstem_count = 0;
   117      vstem_count = 0;
   118      pt.init ();
   119      callStack.init ();
   120      globalSubrs.init (globalSubrs_);
   121      localSubrs.init (localSubrs_);
