   123    inline void fini (void)
   124    {
   125      InterpEnv<ARG>::fini ();
   126
   127      callStack.fini ();
   128      globalSubrs.fini ();
   129      localSubrs.fini ();
   130    }
   131
   132    inline bool in_error (void) const
   133    {
   134      return callStack.in_error () || SUPER::in_error ();
   135    }
   136
   137    inline bool popSubrNum (const BiasedSubrs<SUBRS>& biasedSubrs, unsigned int &subr_num)
   138    {
   139      int n = SUPER::argStack.pop_int ();
   140      n += biasedSubrs.bias;
   141      if (unlikely ((n < 0) || ((unsigned int)n >= biasedSubrs.subrs->count)))
   142        return false;
   143
   144      subr_num = (unsigned int)n;
   145      return true;
   146    }
   147
   148    inline void callSubr (const BiasedSubrs<SUBRS>& biasedSubrs, CSType type)
   149    {
   150      unsigned int subr_num;
   151
   152      if (unlikely (!popSubrNum (biasedSubrs, subr_num)
   153                   || callStack.get_count () >= kMaxCallLimit))
   154      {
   155        SUPER::set_error ();
   156        return;
   157      }
   158      context.substr = SUPER::substr;
   159      callStack.push (context);
   160
   161      context.init ( (*biasedSubrs.subrs)[subr_num], type, subr_num);
   162      SUPER::substr = context.substr;
   163    }
   164
   165    inline void returnFromSubr (void)
   166    {
   167      if (unlikely (SUPER::substr.in_error ()))
   168        SUPER::set_error ();
   169      context = callStack.pop ();
   170      SUPER::substr = context.substr;
   171    }
